from pathlib import Path
import json,math
p=Path(__file__).resolve().parent
raws=[json.loads((p/f'raw/measure-{i}-{id}.json').read_text()) for i,id in enumerate(['control','safe','safe','control'])]
metrics=[]
def pct(v,q):return sorted(v)[math.ceil(len(v)*q)-1]
for r in raws:
 v=[s['renderFinishAndRafMs'] for s in r['metrics']['warmSamples']];sync=[s['submitAndFinishMs'] for s in r['metrics']['warmSamples']]
 assert len(v)==30 and len(r['metrics']['transitions'])==16 and not r['errors']
 metrics.append({'model':r['model'],'order':r['order'],'load':r['metrics']['load'],'contextColdSynchronousCompileMs':r['metrics']['coldCompileMs'],'firstRenderedFrame':r['metrics']['firstRender'],'warmRenderFinishAndRafMs':{'samples':len(v),'p50':pct(v,.5),'p95':pct(v,.95),'min':min(v),'max':max(v)},'warmSubmitAndFinishMs':{'samples':len(sync),'p50':pct(sync,.5),'p95':pct(sync,.95)},'rendererCounts':r['metrics']['firstInfo'],'transitions':len(r['metrics']['transitions']),'errors':r['errors'],'resource':r['metrics']['resourceTiming'],'network':r['network'],'gpu':r['metrics']['gpu']})
result={'status':'diagnostic; no final acceptance','completedOrder':[x['model'] for x in metrics],'percentileMethod':'nearest rank: sorted[ceil(n*p)-1]','firstCorrectFrame':{'status':'unavailable','value':None,'reason':'No correctness inspection at first-render timestamp'},'scope':'Four ABBA completed fresh contexts; a separate browser process per context. HTTP no-store; driver/OS caches and host scheduling uncontrolled. Software-renderer only, no production GPU ranking. PMREM and basis native prefetch excluded from model-load start. Calls/triangles include transmission prepass and main render, reset once per top-level render; not static topology or actual GPU work. Native/sheet packaging overlapped the first control measurement context; timing is not an isolated hardware benchmark. Consult commands.jsonl and tool-attempts.md for failures/timeouts.','measurementNames':{'contextColdSynchronousCompileMs':'CPU elapsed renderer.compile(scene,camera) before first model render; PMREM setup separate, not a claim that browser/driver global caches are cold','cpuSubmitAndFinishMs':'CPU wall duration of renderer.render plus blocking gl.finish','loadToFirstRenderedFrameMs':'Model fetch start to first render plus gl.finish, not first-correct-frame','warmSubmitAndFinishMs':'CPU wall renderer.render plus gl.finish','warmRenderFinishAndRafMs':'CPU wall renderer.render plus gl.finish plus wait for next requestAnimationFrame; not raw GPU timer or display latency'},'measurements':metrics}
(p/'metrics-summary.json').write_text(json.dumps(result,indent=2)+'\n')
print(json.dumps({'order':result['completedOrder'],'warmSamples':sum(x['warmRenderFinishAndRafMs']['samples'] for x in metrics),'transitions':sum(x['transitions'] for x in metrics),'rows':[{'model':x['model'],'order':x['order'],'compileMs':x['contextColdSynchronousCompileMs'],'warmRenderFinishRaf':x['warmRenderFinishAndRafMs'],'warmSubmitFinish':x['warmSubmitAndFinishMs']} for x in metrics]},indent=2))
